use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

struct Node;

/// How many model/tool rounds we allow before giving up. Bounded so a model
/// that keeps asking for tools can never spin the loop forever.
const MAX_ROUNDS: usize = 8;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // `requires len(question) <= 512` holds of every input by contract.
        // We keep a defensive guard anyway; it costs nothing and never fires
        // for well-formed inputs.
        if ctx.question.len() > 512 {
            return ResponseResult::Error(LlmError {
                message: "question exceeds 512 bytes".to_string(),
            });
        }

        let system = concat!(
            "You are a customer-support agent. Answer the user's question using ",
            "only the supplied knowledge and, when needed, the `lookup` tool ",
            "against the knowledge base. Be concise and do not fabricate facts."
        );

        // Seed the prompt with the intent, the bounded question, and whatever
        // knowledge the upstream node already attached.
        let mut prompt = String::new();
        prompt.push_str("intent: ");
        prompt.push_str(intent_label(ctx.intent));
        prompt.push_str("\nquestion: ");
        prompt.push_str(&ctx.question);
        if !ctx.knowledge.is_empty() {
            prompt.push_str("\nknowledge:");
            for k in &ctx.knowledge {
                prompt.push_str("\n- ");
                prompt.push_str(k);
            }
        }

        // Tool-orchestration loop. The model either answers (text) or asks for
        // a tool (call). The only tool this node is authorised to invoke is
        // `lookup`, because `kb-read` is the only tool interface in its world;
        // any other requested tool is reported back to the model as unavailable
        // rather than invoked.
        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(system, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    if req.tool == "lookup" {
                        let hits = kb_read::lookup(&req.query);
                        prompt.push_str("\n[lookup \"");
                        prompt.push_str(&req.query);
                        prompt.push_str("\"]");
                        if hits.is_empty() {
                            prompt.push_str("\n(no results)");
                        } else {
                            for hit in &hits {
                                prompt.push_str("\n- ");
                                prompt.push_str(hit);
                            }
                        }
                    } else {
                        // Not in this node's authority. Tell the model so it can
                        // proceed without it; do not attempt the call.
                        prompt.push_str("\n[tool \"");
                        prompt.push_str(&req.tool);
                        prompt.push_str("\" is not available to this node]");
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool-orchestration loop did not converge on an answer".to_string(),
        })
    }
}

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

export!(Node);
```

